public class DemoMediaLibraryProvider : INotionMediaLibraryProvider
{
    private static readonly List<MediaItem> _items =
    [
        new() { Id = "img1", Url = "https://example.com/hero.png",  Name = "Hero image",  MediaType = "image", FileSizeBytes = 42000 },
        new() { Id = "pdf1", Url = "https://example.com/report.pdf", Name = "Q4 Report",   MediaType = "pdf",   FileSizeBytes = 204800 },
    ];

    public Task<IEnumerable<INotionMediaLibraryItem>> SearchAsync(
        string query, string? mediaType = null, int skip = 0, int take = 24,
        CancellationToken ct = default)
    {
        IEnumerable<MediaItem> result = _items;
        if (!string.IsNullOrWhiteSpace(query))
            result = result.Where(i => i.Name.Contains(query, StringComparison.OrdinalIgnoreCase));
        if (mediaType != null)
            result = result.Where(i => i.MediaType == mediaType);
        return Task.FromResult(result.Skip(skip).Take(take).Cast<INotionMediaLibraryItem>());
    }
}
